import json
import os
import socket
import threading
import time
import traceback
import uuid

try:
    from http.server import BaseHTTPRequestHandler, HTTPServer
    from socketserver import ThreadingMixIn
except ImportError:  # pragma: no cover - Kodi/Python 2 compatibility
    from BaseHTTPServer import BaseHTTPRequestHandler, HTTPServer
    from SocketServer import ThreadingMixIn

from kodi_six import xbmc, xbmcgui

from elementum.addon import ADDON_PATH
from elementum.logger import log
from .dialog import *  # NOQA


_WEB_BRIDGE_PORT = 65222
_WEB_ARM_TIMEOUT = 15.0
_bridge_lock = threading.RLock()
_bridge_armed_until = 0.0
_bridge_window = None
_bridge_server_started = False


def _bridge_arm_web():
    global _bridge_armed_until, _bridge_window

    old_window = None
    with _bridge_lock:
        old_window = _bridge_window
        _bridge_window = None
        _bridge_armed_until = time.time() + _WEB_ARM_TIMEOUT

    if old_window is not None:
        try:
            with old_window.lock:
                old_window.retval = -1
                old_window.value = ''
                old_window.finished = True
        except Exception:
            pass


def _bridge_consume_web_arm():
    global _bridge_armed_until

    with _bridge_lock:
        if time.time() > _bridge_armed_until:
            _bridge_armed_until = 0.0
            return False

        _bridge_armed_until = 0.0
        return True


def _bridge_attach(window):
    global _bridge_window

    with _bridge_lock:
        _bridge_window = window


def _bridge_detach(window):
    global _bridge_window

    with _bridge_lock:
        if _bridge_window is window:
            _bridge_window = None


def _bridge_get_window():
    with _bridge_lock:
        return _bridge_window


def _bridge_state():
    window = _bridge_get_window()
    if window is None:
        return {
            'active': False,
            'armed': time.time() <= _bridge_armed_until,
        }

    with window.lock:
        return {
            'active': True,
            'session': window.web_session_id,
            'mode': 'web' if window.web_mode else 'kodi',
            'title': window.title,
            'items': list(window.items),
            'done': bool(window.finished),
            'choice': int(window.retval),
            'updated_at': window.web_updated_at,
        }


def _bridge_finish(choice, session=''):
    window = _bridge_get_window()
    if window is None:
        return False, 'No active torrent selection'

    with window.lock:
        if session and session != window.web_session_id:
            return False, 'Progressive session does not match'

        if choice < 0:
            window.retval = -1
            window.value = ''
        elif choice >= len(window.items):
            return False, 'Torrent index is out of range'
        else:
            window.retval = int(choice)
            window.value = window.items[choice]

        window.finished = True
        window.web_updated_at = time.time()

    return True, None


class _ThreadingHTTPServer(ThreadingMixIn, HTTPServer):
    daemon_threads = True
    allow_reuse_address = True


class _ProgressiveHandler(BaseHTTPRequestHandler):
    server_version = 'ElementumProgressiveBridge/2.0'

    def log_message(self, message_format, *args):
        log.debug('Progressive bridge: %s' % (message_format % args))

    def _send_json(self, status, value):
        payload = json.dumps(value, ensure_ascii=False).encode('utf-8')
        self.send_response(status)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Content-Length', str(len(payload)))
        self.send_header('Cache-Control', 'no-store')
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type')
        self.send_header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
        self.end_headers()
        self.wfile.write(payload)

    def _read_json(self):
        try:
            length = int(self.headers.get('Content-Length', '0'))
        except Exception:
            length = 0

        if length <= 0:
            return {}
        if length > 65536:
            raise ValueError('Request body is too large')

        body = self.rfile.read(length)
        if not body:
            return {}
        return json.loads(body.decode('utf-8'))

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type')
        self.send_header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
        self.end_headers()

    def do_GET(self):
        if self.path == '/health':
            self._send_json(200, {
                'status': 'ok',
                'hostname': socket.gethostname(),
                'state': _bridge_state(),
            })
            return

        if self.path == '/state':
            self._send_json(200, _bridge_state())
            return

        self._send_json(404, {'error': 'Not found'})

    def do_POST(self):
        if self.path == '/arm':
            _bridge_arm_web()
            self._send_json(200, {'armed': True})
            return

        if self.path in ('/cancel', '/select'):
            try:
                request = self._read_json()
                choice = -1 if self.path == '/cancel' else int(request.get('choice', -1))
                session = str(request.get('session', '') or '')
            except Exception as exc:
                self._send_json(400, {'error': repr(exc)})
                return

            success, error = _bridge_finish(choice, session)
            self._send_json(
                200 if success else 409,
                {'accepted': success, 'choice': choice, 'error': error}
            )
            return

        self._send_json(404, {'error': 'Not found'})


def _start_bridge_server():
    global _bridge_server_started

    if os.environ.get('ELEMENTUM_PROGRESSIVE_RUNNER') == '1':
        return

    with _bridge_lock:
        if _bridge_server_started:
            return
        _bridge_server_started = True

    def serve():
        try:
            server = _ThreadingHTTPServer(
                ('0.0.0.0', _WEB_BRIDGE_PORT),
                _ProgressiveHandler
            )
            log.info(
                'Elementum progressive bridge listening on port %d'
                % _WEB_BRIDGE_PORT
            )
            server.serve_forever()
        except Exception as exc:
            log.error('Elementum progressive bridge failed: %s' % repr(exc))
            for line in traceback.format_exc().splitlines():
                log.error(line)

    worker = threading.Thread(target=serve, name='elementum-progressive-bridge')
    worker.daemon = True
    worker.start()


_start_bridge_server()


class DialogSelect(xbmcgui.WindowXMLDialog):
    def __init__(self, *args, **kwargs):
        xbmcgui.WindowXML.__init__(self)
        self.items = list(kwargs['items'])
        self.title = kwargs['title']
        self.count = 0
        self.retval = -1
        self.value = ''
        self.initialized = False
        self.finished = False
        self.lock = threading.RLock()
        self.web_mode = _bridge_consume_web_arm()
        self.remote_kodi_mode = False
        self.web_session_id = str(uuid.uuid4())
        self.web_updated_at = time.time()

        if self.web_mode:
            log.info(
                'Progressive dialog redirected to Web UI: session=%s items=%d'
                % (self.web_session_id, len(self.items))
            )

    def show(self):
        if self.web_mode:
            with self.lock:
                self.initialized = True
                self.count = len(self.items)
                self.web_updated_at = time.time()
            _bridge_attach(self)
            return None

        # WindowXMLDialog.show() opened only an empty shell on Kodi 21 and did
        # not dispatch onInit/onClick. Keep this object as the RPC-side state
        # holder and run a real modal dialog in a separate Kodi script.
        with self.lock:
            self.remote_kodi_mode = True
            self.initialized = True
            self.count = len(self.items)
            self.web_updated_at = time.time()
        _bridge_attach(self)

        runner = os.path.join(
            ADDON_PATH,
            'resources',
            'site-packages',
            'elementum',
            'kodi_progressive_runner.py'
        )
        command = 'RunScript("%s","%s")' % (
            runner.replace('"', ''),
            self.web_session_id
        )
        log.info(
            'Progressive Kodi runner requested: session=%s items=%d'
            % (self.web_session_id, self.count)
        )
        xbmc.executebuiltin(command)
        return None

    def doModal(self):
        if not self.web_mode and not self.remote_kodi_mode:
            return super(DialogSelect, self).doModal()

        with self.lock:
            self.initialized = True
            self.count = len(self.items)
            self.web_updated_at = time.time()
        _bridge_attach(self)

        monitor = xbmc.Monitor()
        while not self.finished and not monitor.abortRequested():
            xbmc.sleep(100)

        if monitor.abortRequested() and not self.finished:
            self.retval = -1
            self.value = ''
            self.finished = True

    def onInit(self):
        if self.web_mode or self.remote_kodi_mode:
            return

        try:
            with self.lock:
                log.info(
                    'Progressive dialog onInit: items=%d thread=%s'
                    % (len(self.items), threading.current_thread().name)
                )
                self.getControl(32501).setLabel(self.title)
                self.count = 0
                for item in self.items:
                    self._addItem(item)
                self.initialized = True
                self.setFocusId(32503)
                self._log_control_size('onInit')
        except Exception as exc:
            self._log_exception('onInit', exc)

    def updateItems(self, items):
        try:
            with self.lock:
                self.items = list(items)
                self.web_updated_at = time.time()

                if self.web_mode or self.remote_kodi_mode:
                    self.count = len(self.items)
                    log.info(
                        'Progressive remote update: session=%s mode=%s items=%d'
                        % (
                            self.web_session_id,
                            'web' if self.web_mode else 'kodi',
                            self.count,
                        )
                    )
                    _bridge_attach(self)
                    return

                log.info(
                    'Progressive dialog update requested: items=%d initialized=%s finished=%s thread=%s'
                    % (
                        len(self.items),
                        self.initialized,
                        self.finished,
                        threading.current_thread().name,
                    )
                )
                if not self.initialized or self.finished:
                    return

                list_control = self.getControl(32503)
                selected = list_control.getSelectedPosition()
                list_control.reset()
                self.count = 0
                for item in self.items:
                    self._addItem(item)

                if self.count:
                    list_control.selectItem(min(max(selected, 0), self.count - 1))
                self._log_control_size('update')
        except Exception as exc:
            self._log_exception('updateItems', exc)

    def _log_control_size(self, source):
        try:
            visible_count = self.getControl(32503).size()
        except Exception:
            visible_count = -1
        log.info(
            'Progressive dialog %s complete: added=%d control_size=%d'
            % (source, self.count, visible_count)
        )

    def _log_exception(self, source, exc):
        log.error('Progressive dialog %s failed: %s' % (source, repr(exc)))
        for line in traceback.format_exc().splitlines():
            log.error(line)

    def _addItem(self, item):
        labels = item.split('\n')
        label1 = labels[0]
        label2 = labels[1] if len(labels) > 1 else ''
        icon = labels[2] if len(labels) > 2 else None
        multi = len(labels) > 3 and labels[3] == 'multi'
        self.addItem(label1, label2, icon, multi, item)

    def onClick(self, controlId):
        if controlId == 32500:
            self.close()
        elif controlId == 32503:
            list_control = self.getControl(32503)
            selected = list_control.getSelectedItem()
            if selected:
                self.retval = int(selected.getProperty('index'))
                self.value = selected.getProperty('value')
            self.close()

    def onAction(self, action):
        if action.getId() in [ACTION_PARENT_DIR, KEY_NAV_BACK, ACTION_PREVIOUS_MENU]:  # NOQA
            self.close()

    def close(self):
        with self.lock:
            self.finished = True
            log.info(
                'Progressive dialog close: choice=%d items=%d web=%s remote_kodi=%s'
                % (self.retval, self.count, self.web_mode, self.remote_kodi_mode)
            )

        if self.web_mode or self.remote_kodi_mode:
            _bridge_detach(self)
            return None
        return super(DialogSelect, self).close()

    def result(self):
        with self.lock:
            return {
                'done': self.finished,
                'choice': self.retval,
                'value': self.value,
            }

    def addItem(self, label1, label2, icon=None, multi=False, value=None):
        list_control = self.getControl(32503)
        item = xbmcgui.ListItem(label1, label2)
        item.setProperty('index', str(self.count))
        item.setProperty('value', value or '')
        if multi:
            item.setArt({
                'icon': os.path.join(
                    ADDON_PATH,
                    'resources',
                    'img',
                    'multi-cloud.png'
                )
            })
        elif icon:
            item.setArt({'icon': icon})
        else:
            item.setArt({
                'icon': os.path.join(
                    ADDON_PATH,
                    'resources',
                    'img',
                    'cloud.png'
                )
            })
        list_control.addItem(item)
        self.count += 1
